/**
 * Icon registry — resolves an icon id to its SVG contents.
 *
 * The icons are **vendored as data** in `icon-data.generated.ts` (generated by
 * `npm run icons:gen` from the `feather-icons` package, MIT licensed,
 * (c) 2013-2023 Cole Bemis): only the ids this app uses are shipped, so the
 * bundle does not pull the whole icon set and no icon package is loaded at
 * runtime. Components keep using the shared `IconName` enum and `<app-icon>`.
 */
import { ICON_DATA } from './icon-data.generated';

export interface IconDefinition {
  /** Inner SVG markup, rendered inside the shared `<svg>` shell. */
  contents: string;
}

export function getIcon(name: string): IconDefinition {
  return { contents: ICON_DATA[name] ?? '' };
}
